edBox(height:24),TextField(controller:search,onChanged:(v)=>setState(()=>query=v.trim().toLowerCase()),style:const TextStyle(color:Colors.white),decoration:InputDecoration(hintText:'Search doctors or specialties',hintStyle:const TextStyle(color:_muted),prefixIcon:const Icon(Icons.search,color:_lightMauve),filled:true,fillColor:_surface,border:OutlineInputBorder(borderRadius:BorderRadius.circular(15),borderSide:BorderSide.none))),const SizedBox(height:28),_heading('Popular Services','Explore',()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ClinicDirectoryScreen(service:'All clinics'))),),const SizedBox(height:14),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,childAspectRatio:2.7,crossAxisSpacing:10,mainAxisSpacing:10,children:const ['Check-up','Vaccination','Laboratory','Dental Care'].map((s)=>_ServiceTile(name:s)).toList()),const SizedBox(height:28),_heading('Our Doctors','View all',()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const AllDoctorsScreen())),),const SizedBox(height:6),const Text('Find the right specialist for you',style:TextStyle(color:_muted,fontSize:12)),const SizedBox(height:12),StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:HealthLineFirestoreService.instance.activeDoctors(),builder:(context,s){if(s.hasError)return Text('Could not load doctors: ${s.error}',style:const TextStyle(color:Colors.redAccent));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs.where((d){final x=d.data();return '${x['name']??''} ${x['specialty']??''}'.toLowerCase().contains(query);}).toList();if(docs.isEmpty)return const Text('No published doctors found yet.',style:TextStyle(color:_muted));return SizedBox(height:150,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:docs.length,separatorBuilder:(_,__)=>const SizedBox(width:12),itemBuilder:(context,i){final d=docs[i].data();return SizedBox(width:260,child:Card(color:_surface,child:ListTile(contentPadding:const EdgeInsets.all(14),leading:CircleAvatar(backgroundColor:_mauve.withAlpha(40),child:const Icon(Icons.person_outline,color:_lightMauve)),title:Text((d['name']??'Doctor').toString(),style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold)),subtitle:Text((d['specialty']??'').toString(),style:const TextStyle(color:_muted)),onTap:()=>_openDoctor(context,docs[i].id,d)));}));}),const SizedBox(height:10)])),_bottomNav(context)]))));}
 static Widget _heading(String title,String action,VoidCallback tap)=>Row(children:[Expanded(child:Text(title,style:const TextStyle(color:Colors.white,fontSize:19,fontWeight:FontWeight.bold))),TextButton(onPressed:tap,child:Text(action,style:const TextStyle(color:_lightMauve)))]);
 static Widget _bottomNav(BuildContext context)=>Container(color:_bg,padding:const EdgeInsets.fromLTRB(18,6,18,10),child:Row(children:[_nav(context,Icons.home,'Home',null),_nav(context,Icons.calendar_month,'Schedule','/appointments'),_nav(context,Icons.chat_bubble_outline,'Messages','/messages'),_nav(context,Icons.settings,'Settings','/profile-settings')]));
