 static void _openDoctor(BuildContext c,String id,Map<String,dynamic> doctor)async{final clinicId=(doctor['clinicId']??'').toString();try{final clinic=await FirebaseFirestore.instance.collection('clinics').doc(clinicId).get();if(!c.mounted)return;Navigator.push(c,MaterialPageRoute(builder:(_)=>DoctorAvailabilityScreen(doctorId:id,doctor:doctor,clinicId:clinicId,clinicName:(clinic.data()?['name']??'Clinic').toString())));}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Could not open doctor: $e')));}}
}
class _ServiceTile extends StatelessWidget{final String name;const _ServiceTile({required this.name});@override Widget build(BuildContext context){final icon=switch(name){'Check-up'=>Icons.medical_services_outlined,'Vaccination'=>Icons.vaccines_outlined,'Laboratory'=>Icons.science_outlined,_=>Icons.health_and_safety_outlined};return InkWell(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ClinicDirectoryScreen(service:name))),borderRadius:BorderRadius.circular(15),child:Container(decoration:BoxDecoration(color:_surface,borderRadius:BorderRadius.circular(15),border:Border.all(color:Colors.white.withAlpha(18))),padding:const EdgeInsets.all(12),child:Row(children:[Icon(icon,color:_lightMauve),const SizedBox(width:10),Expanded(child:Text(name,style:const TextStyle(color:Colors.white,fontSize:12,fontWeight:FontWeight.w600)))])));}}
class AllDoctorsScreen extends StatelessWidget{const AllDoctorsScreen({super.key});@override Widget build(BuildContext context)=>Scaffold(backgroundColor:_bg,appBar:AppBar(backgroundColor:_bg,foregroundColor:Colors.white,title:const Text('Our Doctors')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:HealthLineFirestoreService.instance.activeDoctors(),builder:(context,s){if(s.hasError)return Center(child:Text('${s.error}',style:const TextStyle(color:Colors.redAccent)));if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.docs.map((doc){final d=doc.data();return Card(color:_surface,child:ListTile(leading:const CircleAvatar(backgroundColor:Color(0xFF423636),child:Icon(Icons.person,color:_lightMauve)),title:Text((d['name']??'Doctor').toString(),style:const TextStyle(color:Colors.white)),subtitle:Text((d['specialty']??'').toString(),style:const TextStyle(color:_muted)),onTap:()=>_DashboardScreenState._openDoctor(context,doc.id,d)));}).toList());}));}}
